/* TravelConnect — authenticated website + installable PWA.
   Accounts, published journeys, bookings and messages use the SQLite API. */
const app = document.querySelector('#app');
const API_BASE = '/api/v1';
const STORE = 'travelconnect-mvp-v1';
const today = new Date();
const tomorrow = new Date(today.getFullYear(), today.getMonth(), today.getDate() + 1);
const dateISO = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const shortDate = d => new Date(`${d}T12:00:00`).toLocaleDateString('en-ZA', { weekday:'short', day:'numeric', month:'short' });
const money = n => `R ${Number(n || 0).toLocaleString('en-ZA')}`;
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scene = `<svg role="img" aria-label="Decorative illustration of South African mountains and a scenic road" viewBox="0 0 600 380" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="sky" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#FC913C"/><stop offset="1" stop-color="#15284F"/></linearGradient></defs><rect width="600" height="380" fill="url(#sky)"/><circle cx="462" cy="94" r="68" fill="#FFCE6A"/><path d="M0 307 91 159l87 99 100-171 121 149 70-92 131 119v117H0Z" fill="#28416A"/><path d="m0 338 113-79 116 61 97-95 124 88 90-64 60 42v89H0Z" fill="#5C4155"/><path d="m145 380 162-170h56l167 170Z" fill="#EEF5FE"/><path d="m338 232 3 148" stroke="#DE6926" stroke-width="11" stroke-dasharray="23 21"/></svg>`;
const mapArt = `<svg role="img" aria-label="Illustrative—not live—route between origin and destination" viewBox="0 0 620 360" preserveAspectRatio="xMidYMid meet"><rect width="620" height="360" fill="#E4F1EF"/><g stroke="#fff" stroke-width="6" opacity=".8"><path d="M0 66H620M0 142H620M0 222H620M0 307H620M84 0V360M194 0V360M323 0V360M457 0V360M567 0V360"/></g><path d="M63 68C183 84 144 201 295 207s170 60 261 91" fill="none" stroke="white" stroke-width="23" stroke-linecap="round"/><path d="M63 68C183 84 144 201 295 207s170 60 261 91" fill="none" stroke="#D8621B" stroke-width="13" stroke-linecap="round"/><circle cx="63" cy="68" r="19" fill="#D8621B" stroke="white" stroke-width="7"/><circle cx="556" cy="298" r="19" fill="#10B7A7" stroke="white" stroke-width="7"/><circle cx="295" cy="207" r="24" fill="#102345" stroke="white" stroke-width="9"/></svg>`;
const cityOptions = ['Johannesburg','Durban','Pretoria','Polokwane','Cape Town','Stellenbosch','Bloemfontein','Mbombela','Pietermaritzburg','Gqeberha'];
const defaultState = { profile:{name:'Traveller',phone:''}, search:{from:'Johannesburg',to:'Durban',date:dateISO(tomorrow),seats:1}, maxPrice:1000, verifiedOnly:false, bookings:[], published:[], chat:[], ai:[], selected:null, latestBooking:null,activeBooking:null };
function loadState(){try{const v=JSON.parse(localStorage.getItem(STORE)||'{}');return {...defaultState,...v,bookings:[],published:[],chat:[],profile:{...defaultState.profile},search:{...defaultState.search,...(v.search||{})}}}catch{return structuredClone(defaultState)}}
const state=loadState();
let bookingBusy=false;let aiEnabled=false, aiBusy=false, aiProvider='Ollama', aiStatusMessage='';
let googleConfig=null, googleStatus='loading', googleSdk=null, googleBusy=false, googleDiagnostic=null;
const googleIcon='<img src="./assets/google-g.svg" width="22" height="22" alt="" loading="lazy" />';
async function prepareGoogleSignIn(){
 try{
  const result=await apiFetch('/auth/firebase/config');
  googleConfig=result.enabled?result.config:null;
  if(!googleConfig){googleStatus='disabled';render();return;}
  const sdk=await import('./firebase-auth.js');
  await sdk.prepareGoogleAuth(googleConfig);
  googleSdk=sdk;googleStatus='ready';
  // Best-effort diagnostic from the public Firebase project configuration.
  // Never block sign-in solely because Google's diagnostic endpoint is offline.
  try {
   const report=await apiFetch('/auth/firebase/diagnostics');googleDiagnostic=report.data;
   if(['action-required','rejected','incomplete'].includes(googleDiagnostic?.status))googleStatus='configuration-error';
  } catch {googleDiagnostic=null;}
 }catch(error){googleStatus='error';console.warn('Google sign-in setup:',error.message)}
 render();
}
function firebaseLoginError(error){
 const messages={
  'auth/popup-blocked':'Google login popup was blocked. Allow popups for localhost and try again.',
  'auth/unauthorized-domain':'Firebase does not allow this domain. Add localhost in Authentication → Settings → Authorized domains.',
  'auth/operation-not-allowed':'Enable the Google provider in Firebase Authentication → Sign-in method.',
  'auth/invalid-api-key':'The Firebase Web API key is invalid. Recopy your web-app config in .env and restart the server.',
  'auth/network-request-failed':'Google sign-in could not contact Firebase. Check your internet connection and browser restrictions.',
  'auth/internal-error':'Google login failed inside Firebase (auth/internal-error). Verify Google is enabled, the localhost domain is authorized, and the Firebase Web app API key matches this project. Open the app in a normal Chrome tab.',
  'auth/popup-closed-by-user':'Google sign-in window was closed.',
  'auth/invalid-credential':'Google login credentials were rejected. Check Firebase Google provider settings.'
 };
 return messages[error?.code]||('Google login failed: '+(error?.code||'unknown error')+'. Check the Firebase project settings.');
}
async function handleGoogleSignIn(){
 if(googleBusy)return;
 if(googleStatus!=='ready'||!googleSdk){notify('Google sign-in is not ready. Configure Firebase and reload the page.');return}
 googleBusy=true;const linking=Boolean(currentUser);
 try{
  const idToken=await googleSdk.getGoogleIdToken();
  const result=await apiFetch('/auth/google',{method:'POST',body:JSON.stringify({idToken})});
  currentUser=result.user;state.profile.name=currentUser.name;state.profile.phone=currentUser.phone||'';
  notify(linking?'Google account securely linked':'Signed in with Google');
  go(linking?'profile':(afterLogin||'search'));
 }catch(error){
  if(!['auth/popup-closed-by-user','auth/cancelled-popup-request'].includes(error.code)){
   console.warn('Firebase sign-in error code:',String(error?.code||'unknown'));
   notify(firebaseLoginError(error));
   if(googleConfig)void checkGoogleConfiguration(true);
  }
 }finally{googleBusy=false}
}
async function checkGoogleConfiguration(showResult=false){
 try{
  const report=await apiFetch('/auth/firebase/diagnostics');googleDiagnostic=report.data;
  if(['action-required','rejected','incomplete'].includes(googleDiagnostic?.status))googleStatus='configuration-error';
  else if(googleSdk)googleStatus='ready';
  if(showResult){
   const text=(googleDiagnostic?.issues||[]).join(' ')||'Firebase public configuration looks consistent. Google provider must still be enabled in the Firebase Console.';
   notify(text.slice(0,480));
  }
 }catch{if(showResult)notify('Firebase configuration check is unavailable. Check your internet connection.');}
 render();
}
function googleButton(link=false){
 const disabled=googleStatus!=='ready'||googleBusy?'disabled':'';
 const label=link?'Link your Google account':'Continue with Google';
 const help=googleStatus==='disabled'?'Google login activates once you configure Firebase Authentication.':
 googleStatus==='configuration-error'?('Firebase needs attention: '+esc((googleDiagnostic?.issues||['Check settings']).join(' '))):
 googleStatus==='error'?'Google SDK could not load. Check your Firebase settings and internet connection.':
 googleStatus==='loading'?'Checking Firebase configuration…':'Sign in with Google securely through your Firebase project.';
 return `<button type="button" class="google-auth-button" data-action="google-signin" ${disabled}>${googleIcon}<span>${label}</span></button><p class="auth-caption">${help}</p><button type="button" class="firebase-diagnostic-link" data-action="firebase-check">Check Google sign-in configuration</button>`;
}
let adminOverview=null, weatherForCity={}, weatherBusy=false, weatherError="", weatherCity="Johannesburg", weatherDate=dateISO(tomorrow);
let remoteTrips=[], currentUser=null, driverTrips=[], driverBookings=[], adminStats=null, adminDrivers=[], messages=[], chatTripId=null, loginMode='login', afterLogin='search', serverError='', lastBookingRequest='';
const trips=()=>remoteTrips;
const findTrip=id=>trips().find(t=>t.id===id);
const initials=name=>String(name).trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
function notify(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('on');clearTimeout(notify.timeout);notify.timeout=setTimeout(()=>t.classList.remove('on'),4000)}
function go(route){location.hash=route;if(location.hash.slice(1)===route)render();window.scrollTo({top:0,behavior:'instant'});refreshRoute(route)}
function btn(label,act,cls=''){return `<button type="button" class="button ${cls}" data-action="${esc(act)}">${esc(label)}</button>`}
function pill(label,cls=''){return `<span class="pill ${cls}">${esc(label)}</span>`}
function citySelect(name,selected){return `<select name="${esc(name)}" required>${cityOptions.map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${esc(c)}</option>`).join('')}</select>`}
function field(label,control){return `<div class="field"><label>${esc(label)}${control}</label></div>`}
function directionsUrl(from,to){const p=new URLSearchParams({api:"1",origin:from+", South Africa",destination:to+", South Africa",travelmode:"driving"});return `https://www.google.com/maps/dir/?${p}`;}
function searchForm(){return `<form id="search-form" class="search-panel"><div class="search-grid">${field('Leaving from',citySelect('from',state.search.from))}${field('Going to',citySelect('to',state.search.to))}${field('Travel date',`<input type="date" name="date" min="${dateISO(today)}" value="${esc(state.search.date)}" required/>`)}${field('Passengers',`<select name="seats">${[1,2,3,4].map(n=>`<option ${state.search.seats===n?'selected':''} value="${n}">${n} ${n===1?'seat':'seats'}</option>`).join('')}</select>`)}<button class="button" type="submit">Search journeys <span class="btn-arrow">→</span></button></div></form>`}
function home(){return `<section class="hero"><div class="hero-orb one"></div><div class="hero-orb two"></div><div class="container hero-grid"><div class="hero-copy">${pill('✦ MADE FOR THE JOURNEY','dark')}<h1>Go further.<br/>Together.</h1><p>Discover long-distance rides across South Africa, meet verified drivers and make every kilometre count.</p><div class="hero-buttons">${btn('Find a ride →','browse')}${btn('Drive with TravelConnect','driver','secondary')}</div><div class="hero-trust"><span>✓ Database-backed bookings</span><span>✓ Approved driver accounts</span><span>✓ Secure trip chat</span></div></div><div class="scene">${scene}<div class="scene-floating"><span class="scene-avatar">↗</span><div><strong>Johannesburg → Durban</strong><small>Route illustration · example only</small></div><span class="money">R 380</span></div></div></div></section><div class="container search-offset">${searchForm()}</div><div class="container"><section class="page-section"><div class="feature-row">${[['✓','Admin-approved driver profiles','Internal account review'],['◈','Smart trip matching','Search compatible routes'],['⌖','Journey coordination','Connect with your driver'],['✦','TripAI assistant','Plan with confidence']].map(([icon,title,detail])=>`<div class="feature"><span class="iconline">${icon}</span><div><strong>${title}</strong><span>${detail}</span></div></div>`).join('')}</div></section><section class="weather-home-banner"><div class="weather-home-icon">☀</div><div><span class="eyebrow">NEW · REAL WEATHER DATA</span><h3>Know the forecast before you go</h3><p>Check city forecasts from Open-Meteo, including rain probability and temperature.</p></div>${btn('Check the weather →','weather','secondary')}</section><section class="page-section"><div class="section-head"><div><h2>Popular routes</h2><p>Explore convenient journeys between cities and communities.</p></div><button class="link" data-action="browse">Browse all →</button></div><div class="route-grid">${[['Johannesburg','Pretoria','Frequent departures'],['Johannesburg','Durban','Long-distance favourite'],['Cape Town','Stellenbosch','Weekend inspiration']].map(([from,to,subtitle])=>`<button class="route-tile" data-action="route" data-from="${esc(from)}" data-to="${esc(to)}"><span class="eyebrow">POPULAR ROUTE</span><strong>${esc(from)} → ${esc(to)}</strong><small>${esc(subtitle)}</small></button>`).join('')}</div></section><section class="page-section"><div class="section-head"><div><h2>How TravelConnect works</h2><p>Designed for passengers and drivers, one journey at a time.</p></div></div><div class="how-grid">${[['01','Find a journey','Search journeys offered by approved drivers.'],['02','Reserve a seat','Review the details and reserve available seats on the server.'],['03','Stay connected','Message trip participants and review your booking.']].map(([n,title,detail])=>`<div class="how-card"><span class="how-num">${n}</span><h3>${title}</h3><p>${detail}</p></div>`).join('')}</div></section><div class="app-banner"><div><span class="eyebrow">YOUR JOURNEY, IN YOUR POCKET</span><h2>TravelConnect goes with you.</h2><p>This website adapts to your phone and can be installed as an app from a supported browser.</p></div>${btn('How to install →','install-help')}</div></div>`}
function resultTrips(){return trips().filter(t=>t.from===state.search.from&&t.to===state.search.to&&t.date===state.search.date&&t.seats>=state.search.seats&&t.price<=state.maxPrice&&(!state.verifiedOnly||t.verified));}
function tripCard(t){return `<article class="ride-card"><div><div class="ride-when">${esc(t.depart)} <span>→</span> ${esc(t.arrive)}</div><div class="ride-route">${esc(t.pickup)}, ${esc(t.from)} → ${esc(t.dropoff)}, ${esc(t.to)} · ${esc(shortDate(t.date))}</div><div class="ride-divider"></div><div class="ride-bottom"><div class="driver-person"><span class="driver-avatar">${esc(t.initials)}</span><div><strong>${esc(t.driver)}</strong><small><span class="star">★</span> ${esc(t.rating)} · ${esc(t.seats)} seats available</small></div></div></div><div class="badge-row">${t.verified?pill('✓ Admin approved','green'):pill('Pending verification','orange')}${t.ac?pill('Air conditioning'):''}${t.luggage?pill('Luggage space'):''}</div></div><div class="price-col"><strong>${money(t.price)}</strong><small>per seat · reservation fare</small><button class="button small" data-action="detail" data-id="${esc(t.id)}">View ride →</button></div></article>`}
function search(){const matching=resultTrips();return `<div class="container page-shell"><div class="page-heading"><div><h2>Find your next journey</h2><p>Search current journeys published by approved drivers.</p></div></div>${serverError?`<div class="legal-note">${esc(serverError)}</div>`:''}<div class="browse-layout"><aside class="filters surface"><button class="mobile-filter" id="filter-toggle">Filters ☷</button><div class="filter-inner"><h3>Refine your search</h3>${field('From',citySelect('filter-from',state.search.from))}${field('To',citySelect('filter-to',state.search.to))}<div class="divider"></div><h4>Maximum price per seat</h4><div class="field"><select id="filter-price">${[200,400,600,1000,2000,5000].map(v=>`<option value="${v}" ${state.maxPrice===v?'selected':''}>Up to ${money(v)}</option>`).join('')}</select></div><h4>Preferences</h4><label class="check-row"><input type="checkbox" id="filter-verified" ${state.verifiedOnly?'checked':''}/> Approved drivers only</label><p class="muted" style="font-size:.78rem;margin-top:18px">Only active journeys from approved driver accounts are shown.</p></div></aside><div><div class="result-bar"><span>${esc(state.search.from)}</span><span class="direction">→</span><span>${esc(state.search.to)}</span><small>${esc(shortDate(state.search.date))} · ${state.search.seats} seat(s)</small></div><div class="result-meta"><h3>${matching.length} available ride(s)</h3><span class="pill">Sorted by departure</span></div><div class="ride-list">${matching.length?matching.sort((a,b)=>a.depart.localeCompare(b.depart)).map(tripCard).join(''):`<div class="empty"><div class="emoji">⌕</div><h3>No journeys available yet</h3><p>Try another route or date. Approved drivers can publish new journeys as they join TravelConnect.</p>${btn('Change search','reset-search')}</div>`}</div></div></div></div>`}
function scenic(){return `<div class="illustration">${scene}<span class="pill scenic-tag">Illustrative journey</span></div>`}
function routeSteps(t){return `<div class="route-steps"><span class="route-circle"></span><div><strong>${esc(t.from)}</strong><span>${esc(t.pickup)} · ${esc(t.depart)}</span></div><span class="rail"></span><span></span><span class="route-circle teal"></span><div><strong>${esc(t.to)}</strong><span>${esc(t.dropoff)} · ${esc(t.arrive)}</span></div></div>`}
function detail(){const t=findTrip(state.selected);if(!t)return search();return `<div class="container page-shell"><button class="back-link" data-action="browse">← Back to results</button><div class="page-heading"><div><h2>${esc(t.from)} to ${esc(t.to)}</h2><p>${esc(shortDate(t.date))} · Departs ${esc(t.depart)} · ${esc(t.vehicle)}</p></div>${pill('✓ Admin-approved driver','green')}</div><div class="detail-grid"><div>${scenic()}<section class="detail-block"><h3>About your driver</h3><div class="driver-summary"><span class="driver-avatar">${esc(t.initials)}</span><div><strong>${esc(t.driver)}</strong><p class="muted">Approved TravelConnect driver profile. External licence/document verification is not yet integrated.</p></div></div><div class="detail-data"><div><span>Vehicle</span><strong>${esc(t.vehicle)}</strong></div><div><span>Seats remaining</span><strong>${t.seats} available</strong></div></div></section><section class="detail-block"><h3>Your route</h3>${routeSteps(t)}</section><section class="detail-block"><div class="section-head"><div><h3>Forecast for your arrival city</h3><p>Real model forecast, not vehicle tracking.</p></div><button class="button secondary small" data-action="trip-weather" data-city="${esc(t.to)}" data-date="${esc(t.date)}">Update forecast</button></div>${weatherCard(t.to,t.date)}<a class="directions-link" href="${esc(directionsUrl(t.from,t.to))}" target="_blank" rel="noopener noreferrer">Open route in Google Maps ↗</a></section><section class="detail-block"><h3>Journey information</h3><p>Confirm pickup details and arrangements with your driver through the booking chat. GPS tracking and payments are not yet available.</p></section></div><aside class="booking-aside surface"><span class="eyebrow">PRICE PER SEAT</span><div class="price">${money(t.price)} <span>/ passenger</span></div><p>${esc(shortDate(t.date))} · ${esc(t.depart)}</p><div class="divider"></div><div class="fare-line"><span>${state.search.seats} × ${money(t.price)}</span><strong>${money(t.price*state.search.seats)}</strong></div><div class="fare-line fare-total"><span>Reservation amount</span><strong>${money(t.price*state.search.seats)}</strong></div><button class="button full" data-action="checkout">Reserve this seat →</button><p>No payment is collected yet. A reservation will hold available seats in the database.</p></aside></div></div>`}
function checkout(){const t=findTrip(state.selected);if(!t)return search();return `<div class="container page-shell"><button class="back-link" data-action="detail" data-id="${esc(t.id)}">← Back to journey</button><div class="page-heading"><div><h2>Confirm your reservation</h2><p>${currentUser?'Your account is signed in. Review before reserving.':'Sign in to make a reservation.'}</p></div></div><div class="detail-grid"><section class="order-card surface"><h3>Journey details</h3><div class="driver-summary" style="margin-top:18px"><span class="driver-avatar">${esc(t.initials)}</span><div><strong>${esc(t.driver)}</strong><p class="muted">${esc(t.vehicle)} · ${esc(shortDate(t.date))}</p></div></div><div class="divider"></div>${routeSteps(t)}<div class="legal-note">This reservation holds seats in the TravelConnect database. Payment processing, GPS tracking and automated driver identity checks are not yet connected. Confirm transport arrangements before travel.</div></section><aside class="surface booking-aside"><h3>Reservation details</h3><div class="fare-line"><span>${state.search.seats} seat(s)</span><strong>${money(state.search.seats*t.price)}</strong></div><div class="fare-line"><span>Paid online</span><strong>R 0</strong></div><div class="fare-line fare-total"><span>Fare to arrange</span><strong>${money(state.search.seats*t.price)}</strong></div><button class="button full" data-action="confirm-booking">${currentUser?'Reserve seats →':'Sign in to reserve →'}</button></aside></div></div>`}
function booked(){const b=state.bookings.find(x=>x.id===state.latestBooking);if(!b)return myTrips();return `<div class="container page-shell"><div class="success-pane surface"><div class="success-mark">✓</div><h2>Seats reserved!</h2><p>Your reservation is recorded on the server. Reference: <strong>${esc(b.id)}</strong>. You have <strong>${esc(b.seats)} seat(s)</strong> reserved. No payment was processed.</p><div class="buttons">${btn('View my journeys →','my-trips')}${btn('Search more rides','browse','secondary')}</div></div></div>`}
function myTrips(){if(!currentUser)return loginRequired('Sign in to view your journeys');return `<div class="container page-shell"><div class="page-heading"><div><h2>My journeys</h2><p>Your bookings are saved in the TravelConnect database.</p></div>${btn('Find a ride','browse','small')}</div>${state.bookings.length?`<div class="trip-grid">${state.bookings.map(b=>`<article class="trip-card surface"><div class="trip-header">${pill(b.status==='reserved'?'Reserved':'Cancelled',b.status==='reserved'?'green':'orange')}<small>${esc(b.id.slice(0,8).toUpperCase())}</small></div><h3>${esc(b.from)} → ${esc(b.to)}</h3><p class="muted">Driver: ${esc(b.driver||'Driver')}</p><small>${esc(shortDate(b.date))} · ${esc(b.depart)} · ${esc(b.seats)} seat(s)</small><div class="fare-line"><span>Fare (not paid online)</span><strong>${money(b.total)}</strong></div>${b.status==='reserved'?`<div class="buttons"><button class="button small" data-action="track" data-id="${esc(b.id)}">Open journey →</button><button class="button secondary small" data-action="cancel-booking" data-id="${esc(b.id)}">Cancel reservation</button></div>`:''}</article>`).join('')}</div>`:`<div class="empty"><div class="emoji">⌖</div><h3>No journeys yet</h3><p>Browse available journeys and reserve a seat to see your booking here.</p>${btn('Browse rides','browse')}</div>`}</div>`}
function track(){const b=state.bookings.find(x=>x.id===state.activeBooking)||state.bookings[0];if(!b)return myTrips();const t=findTrip(b.tripId);return `<div class="container page-shell"><button class="back-link" data-action="my-trips">← My journeys</button><div class="page-heading"><div><h2>${esc(b.from)} → ${esc(b.to)}</h2><p>${esc(shortDate(b.date))} · Reservation ${esc(b.id.slice(0,8).toUpperCase())}</p></div>${pill('Reservation '+b.status,b.status==='reserved'?'green':'orange')}</div><div class="tracking-panel"><div class="surface" style="padding:20px"><div class="tripmap">${mapArt}<span class="map-tag">Illustrative route · NOT live GPS</span></div><div class="detail-data"><div><span>Departure</span><strong>${esc(b.depart)}</strong></div><div><span>Estimated arrival</span><strong>${esc(b.arrive||'TBC')}</strong></div></div><a class="directions-link" href="${esc(directionsUrl(b.from,b.to))}" target="_blank" rel="noopener noreferrer">View driving directions in Google Maps ↗</a><div class="legal-note">Real-time vehicle positions and emergency dispatch are not active. Do not rely on this illustration to locate a vehicle.</div></div><aside><div class="surface" style="padding:24px;margin-bottom:20px"><h3>Journey details</h3><p>${esc(b.driver||'')} · ${esc(b.vehicle||'')}</p><button class="button full" data-action="chat">Open trip messages →</button></div><div class="surface" style="padding:24px"><h3>Safety information</h3><p class="muted">Contact your driver, confirm vehicle and meeting location, and arrange a trusted contact before travel.</p><button class="button secondary full" style="margin-top:18px" data-action="safety">Safety information</button></div></aside></div></div>`}
function chat(){if(!currentUser)return loginRequired('Sign in to message a journey');if(!chatTripId)return myTrips();return `<div class="container page-shell"><button class="back-link" data-action="${currentUser.role==='driver'?'driver':'my-trips'}">← Back</button><div class="page-heading"><div><h2>Trip messages</h2><p>Messages are saved on the TravelConnect server and visible only to the trip's booked passengers and driver.</p></div></div><div class="chat-card"><div class="chat-head"><span class="driver-avatar">TC</span><div><strong>Journey conversation</strong><p class="muted" style="font-size:.8rem">Private trip discussion · use Refresh to see new messages</p></div></div><div style="padding:10px 20px"><button class="button secondary small" data-action="refresh-chat">Refresh messages</button></div><div class="chat-messages">${messages.length?messages.map(m=>`<div class="message ${m.mine?'mine':''}"><div class="name">${esc(m.author)}</div>${esc(m.content)}</div>`).join(''):'<p class="muted" style="padding:18px">No messages yet. Introduce yourself and confirm pickup details.</p>'}</div><form class="compose" id="chat-form"><input name="message" maxlength="1000" aria-label="Message" placeholder="Write a message..." required/><button class="button small" type="submit">Send</button></form></div></div>`}
function aiReply(question){const q=question.toLowerCase();if(/weather|rain|forecast|temperature|wind/.test(q))return 'Real city forecasts are now available on the Weather page, with Open-Meteo as the data source. Select your destination and date there. This chat itself does not use a third-party language-model API.';if(/safety|verified|licence|emergency|sos/.test(q))return 'TravelConnect plans driver and vehicle verification, trip PINs, and controlled sharing. The current demo does not verify identities or contact emergency services.';if(/cheap|affordable|budget|fare|cost|price|durban|pretoria|trip|ride/.test(q)){const matches=trips().filter(t=>t.from===state.search.from&&t.to===state.search.to).sort((a,b)=>a.price-b.price);return matches.length?`Among currently published journeys for ${state.search.from} → ${state.search.to}, the lowest displayed fare is ${money(matches[0].price)} with ${matches[0].driver}. Availability can change; confirm in Find rides.`:'No published journey matches your current route. Open Find rides to search another route.';}return 'I can help you plan trips, compare example fares and understand the safety features. The AI provider is not connected in this starter, so this response uses clearly labelled demo rules.'}
function weatherCard(city,date){const data=weatherForCity[city+":"+date];if(!data)return `<div class="weather-empty"><span class="weather-symbol">☁</span><div><strong>Live forecast for ${esc(city)}</strong><span>Choose “Update forecast” to check the current provider forecast.</span></div></div>`;
const f=data.forecast;return `<div class="weather-summary"><div class="weather-temperature"><span class="weather-symbol">${f.rainChance>=55?'☂':f.conditions==='Clear sky'?'☀':'☁'}</span><div><strong>${Number.isFinite(f.high)?Math.round(f.high)+'°C':'—'}</strong><span>High · ${esc(shortDate(data.date))}</span></div></div><div class="weather-facts"><span>${esc(f.conditions)}</span><span>Rain probability: <b>${Number.isFinite(f.rainChance)?f.rainChance+'%':'—'}</b></span><span>Low: <b>${Number.isFinite(f.low)?Math.round(f.low)+'°C':'—'}</b></span></div></div><p class="weather-credit">Forecast data by <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a>. Model forecast, not an official travel safety warning. Checked ${esc(new Date(data.updatedAt).toLocaleString('en-ZA'))}.</p>`}
function weatherPage(){return `<div class="container page-shell weather-page"><div class="page-heading"><div><span class="eyebrow">REAL FORECAST API · SOUTH AFRICA</span><h2>Weather for your journey</h2><p>Check the current weather model for your departure or arrival city. No GPS access required.</p></div>${pill('Forecast data · Open-Meteo','green')}</div><div class="weather-layout"><section class="surface weather-picker"><h3>Check a destination</h3><p class="muted" style="margin:10px 0 22px">Choose a city and date within the provider’s forecast window.</p><form id="weather-form">${field('Destination city',citySelect('weather-city',weatherCity))}${field('Travel date',`<input type="date" name="weather-date" value="${esc(weatherDate)}" min="${dateISO(today)}" max="${dateISO(new Date(Date.now()+15*86400000))}" required/>`)}<button class="button full" type="submit" style="margin-top:23px" ${weatherBusy?'disabled':''}>${weatherBusy?'Checking forecast…':'Get real forecast →'}</button></form><p class="muted" style="margin-top:22px;font-size:.78rem">Weather may change quickly. Always verify conditions with official local sources before departing.</p></section><section class="surface weather-result"><span class="eyebrow">${esc(weatherCity.toUpperCase())} · ${esc(shortDate(weatherDate))}</span><h3>Destination forecast</h3>${weatherError?`<div class="legal-note">${esc(weatherError)}</div>`:weatherCard(weatherCity,weatherDate)}<div class="weather-provider"><span class="provider-pulse"></span>Server-to-server data · Cached for 15 minutes · <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a></div></section></div><section class="weather-cities"><div class="section-head"><div><h2>Check a popular city</h2><p>Quick access to destination forecasts.</p></div></div><div class="weather-city-grid">${['Johannesburg','Durban','Cape Town','Pretoria'].map((c,i)=>`<button class="weather-city-tile weather-city-${i}" type="button" data-action="weather-city" data-city="${esc(c)}"><span class="weather-city-icon">${['☀','☁','◌','☀'][i]}</span><strong>${esc(c)}</strong><small>Check weather ↗</small></button>`).join('')}</div></section></div>`}
async function fetchWeather(city,date){weatherBusy=true;weatherError='';weatherCity=city;weatherDate=date;render();try{const r=await apiFetch('/weather?'+new URLSearchParams({city,date}));weatherForCity[city+":"+date]=r.data;}catch(error){weatherError=error.message;}finally{weatherBusy=false;render();}}
function assistant(){const sample=[{name:'TripAI · sample',text:'Welcome! Try asking about affordable trips, weather, or driver safety.',mine:false}];return `<div class="container page-shell"><div class="page-heading"><div><h2>Meet TripAI <span style="color:var(--teal)">✦</span></h2><p>${aiEnabled?'Real '+esc(aiProvider)+' responses · check important information':esc(aiStatusMessage||'Install the free local model to enable TripAI')}</p></div></div><div class="ai-layout"><div class="ai-hero"><span class="pill dark">✦ TRAVEL SMARTER</span><h2>Where can I take you?</h2><p>Find example journeys, understand travel safety, and explore the future of intelligent trip planning.</p><div class="suggestions">${['Find an affordable ride to Durban','What happens during driver verification?','Will it rain along my route?'].map(q=>`<button class="suggestion" data-action="ask" data-question="${esc(q)}">${esc(q)} →</button>`).join('')}</div></div><div class="chat-card chat-wrap"><div class="chat-head"><span class="iconline green">✦</span><div><strong>TripAI Assistant</strong><p class="muted" style="font-size:.8rem">${aiEnabled?esc(aiProvider)+' model connected · verify important information':'Free AI not connected yet'}</p></div></div><div class="chat-messages" id="ai-messages">${[...sample,...state.ai].map(m=>`<div class="message ${m.mine?'mine':''}"><div class="name">${esc(m.name)}</div>${esc(m.text)}</div>`).join('')}</div><form class="compose" id="ai-form"><input name="question" maxlength="500" placeholder="Ask TripAI something..." aria-label="Ask TripAI" required/><button class="button small" type="submit">Send</button></form><div class="ai-disclaimer">${aiEnabled?(aiProvider==='Ollama'?'Your questions are processed locally by Ollama on your Mac. No paid AI API.': 'AI requests go from our server to '+esc(aiProvider)+'. Never share private information. Free-tier quotas may apply.') : esc(aiStatusMessage||'Start Ollama to use real free AI. No OpenAI billing is required.')}</div></div></div></div>`}
function driver() {
  if(!currentUser) return loginRequired('Sign in to drive with TravelConnect');
  if(currentUser.role==='passenger'||currentUser.driver_status==='rejected') {
    return `<div class="container page-shell"><div class="page-heading"><div><h2>Become a TravelConnect driver</h2><p>Apply for manual review before publishing journeys.</p></div></div><section class="surface" style="max-width:610px"><h3>Driver application</h3><p class="muted" style="margin:12px 0">A real administrator must review licences, insurance and vehicle requirements outside this app before approval. Do not upload identity documents here.</p><form id="driver-apply-form">${field('Vehicle description','<input name="vehicle" minlength="3" maxlength="80" placeholder="e.g. Toyota Corolla" required/>')}<button class="button" type="submit" style="margin-top:18px">Submit application</button></form></section></div>`;
  }
  if(currentUser.role==='admin') return `<div class="container page-shell"><section class="surface"><h2>Administrator</h2>${btn('Open admin dashboard','admin')}</section></div>`;
  if(currentUser.driver_status!=='approved') return `<div class="container page-shell"><div class="page-heading"><h2>Driver application awaiting review</h2></div><section class="surface"><p>Your application is <strong>${esc(currentUser.driver_status)}</strong>. Only approved drivers can publish journeys.</p><button class="button secondary" data-action="refresh-account" style="margin-top:18px">Check approval status</button></section></div>`;
  const metrics = [
    [driverTrips.filter(v=>v.status==='published').length,'Active journeys','Visible to passengers'],
    [driverBookings.filter(v=>v.status==='reserved').length,'Reservations','Stored in the database'],
    ['R 0','Payments processed','No payment provider connected']
  ].map(([value,title,subtitle])=>`<div class="surface metric"><span>${esc(title)}</span><strong>${esc(value)}</strong><small>${esc(subtitle)}</small></div>`).join('');
  const listed = driverTrips.length ? driverTrips.map(v=>`<div class="admin-item"><div><strong>${esc(v.from)} → ${esc(v.to)}</strong><small>${esc(shortDate(v.date))} · ${money(v.price)} per seat · ${esc(v.seats)} seats left · ${esc(v.status)}</small></div>${v.status==='published'?`<button class="button subtle small" data-action="delete-trip" data-id="${esc(v.id)}">Cancel</button>`:''}</div>`).join('') : '<p class="muted">No journeys published yet.</p>';
  const passengerBookings = driverBookings.length ? driverBookings.map(v=>`<div class="admin-item"><div><strong>${esc(v.passenger)}</strong><small>${esc(v.origin)} → ${esc(v.destination)} · ${esc(v.seats)} seat(s) · ${esc(v.status)}</small></div>${v.status==='reserved'?`<button class="button small" data-action="driver-chat" data-id="${esc(v.tripId)}">Message</button>`:''}</div>`).join('') : '<p class="muted">No reservations yet.</p>';
  const controls = [
    field('Departure city',citySelect('from','Johannesburg')),
    field('Destination city',citySelect('to','Durban')),
    field('Departure date',`<input type="date" name="date" min="${dateISO(today)}" value="${dateISO(tomorrow)}" required/>`),
    field('Departure time','<input type="time" name="depart" value="07:00" required/>'),
    field('Price per seat (R)','<input type="number" name="price" min="1" max="50000" value="350" required/>'),
    field('Available seats','<input type="number" name="seats" min="1" max="8" value="3" required/>'),
    field('Vehicle',`<input name="vehicle" maxlength="80" value="${esc(currentUser.vehicle||'Toyota Corolla')}" required/>`),
    field('Pickup location','<input name="pickup" maxlength="120" placeholder="e.g. Park Station"/>'),
    field('Drop-off location','<input name="dropoff" maxlength="120" placeholder="e.g. Durban CBD"/>')
  ].join('');
  return `<div class="container page-shell"><div class="driver-heading"><div><span class="eyebrow">DRIVER WORKSPACE</span><h2>Your driver dashboard</h2><p class="muted">Publish journeys and manage your passengers.</p></div>${pill('Admin approved','green')}</div><div class="metric-grid">${metrics}</div><div class="dashboard-layout"><section class="surface"><h3>Publish a journey</h3><p class="muted" style="margin:8px 0 20px">Passenger reservations are recorded centrally. You must comply with transport regulations.</p><form id="publish-form" class="publish-form">${controls}<button class="button full" type="submit">Publish journey</button></form></section><section class="surface"><h3>Your published journeys</h3><div class="divider"></div>${listed}<h3 style="margin-top:26px">Passenger reservations</h3>${passengerBookings}<div class="legal-note">A journey with active bookings cannot be cancelled online.</div></section></div></div>`;
}
function admin(){if(!currentUser||currentUser.role!=='admin')return loginRequired('Administrator access only');
const stats=adminOverview?.stats||adminStats||{};
const metricTiles=[
 ['◫','Registered accounts',stats.users??'—','Stored in the database','blue'],
 ['▣','Active reservations',stats.bookingsReserved??'—',`${stats.seatsReserved??'—'} seats reserved`,'teal'],
 ['↗','Published journeys',stats.tripsPublished??'—','Approved drivers only','purple'],
 ['⚑','Driver reviews pending',stats.driversPending??'—','Awaiting independent checks','orange']
];
const bookings=adminOverview?.recentBookings||[];
const journeys=adminOverview?.recentTrips||[];
const events=adminOverview?.recentActivity||[];
return `<div class="admin-shell"><aside class="admin-sidebar"><div class="admin-side-top"><span class="admin-brand-icon"><img src="./assets/icon-192.png" width="40" height="40" alt="" /></span><div><strong>travelconnect</strong><small>OPERATIONS</small></div></div><div class="admin-side-label">WORKSPACE</div><a class="admin-side-item active" href="#admin"><span>◫</span> Overview</a><button class="admin-side-item" data-action="refresh-admin"><span>◌</span> Refresh data</button><a class="admin-side-item" href="#driver"><span>↗</span> Driver workspace</a><a class="admin-side-item" href="#search"><span>⌕</span> Journey search</a><div class="admin-side-bottom"><span class="admin-side-status"></span><div><strong>Database connected</strong><small>SQLite · Local instance</small></div></div></aside><div class="admin-main"><div class="admin-toolbar"><div class="admin-breadcrumb">WORKSPACE <span>/</span> OVERVIEW</div><div class="admin-toolbar-right"><span class="admin-live-pill"><i></i> Live database</span><span class="admin-initials">${esc(initials(currentUser.name))}</span></div></div><section class="admin-welcome"><div><span class="eyebrow">PLATFORM CONTROL CENTRE</span><h1>Good to see you, ${esc(currentUser.name.split(' ')[0])}.</h1><p>Manage your TravelConnect users, journeys, bookings and driver reviews from one place.</p></div><button class="button" data-action="refresh-admin">↻ Refresh overview</button></section><section class="admin-metrics">${metricTiles.map(([icon,title,value,sub,accent])=>`<article class="admin-metric"><div class="admin-metric-top"><span>${esc(title)}</span><span class="admin-metric-icon ${accent}">${icon}</span></div><strong>${esc(value)}</strong><small>${esc(sub)}</small></article>`).join('')}</section><div class="admin-content-grid"><section class="admin-panel admin-requests"><div class="admin-panel-head"><div><h3>Driver verification queue</h3><p>Review pending applications. Check documents independently.</p></div>${pill(`${adminDrivers.length} pending`,adminDrivers.length?'orange':'green')}</div>${adminDrivers.length?adminDrivers.map(u=>`<article class="admin-request"><span class="admin-user-avatar">${esc(initials(u.name))}</span><div class="admin-request-info"><strong>${esc(u.name)}</strong><span>${esc(u.email)}</span><small>${esc(u.vehicle)}</small></div><div class="admin-request-actions"><button class="button small" data-action="approve-driver" data-id="${esc(u.id)}">Approve</button><button class="button secondary small" data-action="reject-driver" data-id="${esc(u.id)}">Reject</button></div></article>`).join(''):`<div class="admin-empty"><span>✓</span><strong>All caught up</strong><p>No driver applications are waiting for review.</p></div>`}<div class="admin-alert">⚠ Approve only after independently checking licences, insurance and transport compliance. An admin click does not verify identity automatically.</div></section><section class="admin-panel admin-glance"><div class="admin-panel-head"><div><h3>Platform activity</h3><p>Real data from this server, not placeholder statistics.</p></div></div><div class="admin-glance-stats"><div><span>Approved drivers</span><strong>${esc(stats.driversApproved??'—')}</strong></div><div><span>Booked seats</span><strong>${esc(stats.seatsReserved??'—')}</strong></div><div><span>Reserved fare total</span><strong>${money(stats.faresReserved??0)}</strong><small>Not collected or paid</small></div></div><div class="admin-subhead">Recent activity</div><div class="admin-timeline">${events.length?events.slice(0,5).map(item=>`<div class="admin-timeline-item"><span class="admin-timeline-dot"></span><div><strong>${esc(item.action.replaceAll('.',' · '))}</strong><small>${esc(new Date(item.created_at).toLocaleString('en-ZA'))}</small></div></div>`).join(''):'<p class="muted">No recorded events yet.</p>'}</div></section></div><section class="admin-panel admin-table-panel"><div class="admin-panel-head"><div><h3>Recent reservations</h3><p>Actual booking records stored in your database.</p></div><span class="admin-table-count">${bookings.length} recent</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Passenger</th><th>Journey</th><th>Travel date</th><th>Seats</th><th>Fare</th><th>Status</th></tr></thead><tbody>${bookings.length?bookings.map(b=>`<tr><td><strong>${esc(b.passenger)}</strong></td><td>${esc(b.from_city)} → ${esc(b.to_city)}</td><td>${esc(shortDate(b.date))}</td><td>${esc(b.seats)}</td><td>${money(b.total)}</td><td>${pill(b.status,b.status==='reserved'?'green':'orange')}</td></tr>`).join(''):'<tr><td colspan="6" class="admin-table-empty">No reservations yet. Bookings will appear here when passengers reserve seats.</td></tr>'}</tbody></table></div></section><section class="admin-panel admin-table-panel"><div class="admin-panel-head"><div><h3>Journey inventory</h3><p>Recently published and cancelled driver journeys.</p></div><span class="admin-table-count">${journeys.length} recent</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Driver</th><th>Route</th><th>Departure</th><th>Seats available</th><th>Status</th></tr></thead><tbody>${journeys.length?journeys.map(t=>`<tr><td><strong>${esc(t.driver)}</strong></td><td>${esc(t.from_city)} → ${esc(t.to_city)}</td><td>${esc(shortDate(t.date))} · ${esc(t.depart)}</td><td>${esc(t.seats_left)} / ${esc(t.seats_total)}</td><td>${pill(t.status,t.status==='published'?'green':'orange')}</td></tr>`).join(''):'<tr><td colspan="5" class="admin-table-empty">No journeys published yet. Approved drivers can publish the first route.</td></tr>'}</tbody></table></div></section><footer class="admin-footnote">Platform is in early access. Payments, live GPS, external verification and emergency dispatch remain disabled until verified integrations are completed.</footer></div></div>`}
function profile(){if(!currentUser)return authPage();return `<div class="container page-shell"><div class="page-heading"><div><h2>Account settings</h2><p>Your information is stored in the TravelConnect database.</p></div>${pill(esc(currentUser.role),'green')}</div><div class="profile-grid"><section class="surface"><h3>Personal details</h3><p class="muted" style="margin:10px 0 20px">${esc(currentUser.email)}</p><form id="profile-form">${field('Display name',`<input name="name" minlength="2" maxlength="70" value="${esc(currentUser.name)}" required/>`)}${field('Phone (optional)',`<input name="phone" type="tel" maxlength="30" value="${esc(currentUser.phone||'')}"/>`)}<button class="button" type="submit" style="margin-top:18px">Save profile</button></form></section><section class="surface"><h3>Your account</h3><p class="muted" style="margin:14px 0">Role: ${esc(currentUser.role)}. Driver application: ${esc(currentUser.driver_status)}.</p>${currentUser.role==='admin'?btn('Admin console','admin','secondary'):''}${currentUser.googleLinked?'<div class="google-linked">✓ Google sign-in connected to your account</div>':`<div class="auth-divider">Secure sign-in</div>${googleButton(true)}`}<button class="button secondary" data-action="logout" style="margin-top:18px">Sign out</button><div class="divider"></div><p class="muted">To install TravelConnect on another device, open the hosted site over HTTPS and choose Install app. The login connects to the same database from every device.</p></section></div></div>`}
function safety(){return `<div class="container page-shell"><button class="back-link" data-action="my-trips">← Back to journeys</button><div class="page-heading"><div><h2>Travel safety</h2><p>Security and privacy are foundational to TravelConnect.</p></div></div><div class="detail-grid"><div class="detail-block"><h3>Planned safeguards</h3><div class="admin-list">${[['Verified drivers','Identity, professional driving permits where needed and vehicle checks.'],['Trip PIN','An authorised passenger and driver confirm the correct journey.'],['Trusted-contact sharing','Opt-in, time-limited links for a specific journey.'],['Emergency response','Only show confirmation after a real emergency integration succeeds.']].map(([a,b])=>`<div class="admin-item"><div><strong>${a}</strong><small>${b}</small></div></div>`).join('')}</div></div><div class="detail-block"><h3>Current demo limitations</h3><p class="muted">There is no location tracking, no emergency-service contact, no real identity verification, and no secure payment integration. These features must be built and tested before real travel use.</p></div></div></div>`}
function installHelp(){return `<div class="container page-shell"><div class="page-heading"><div><h2>Install TravelConnect</h2><p>A website and phone app from the same responsive PWA codebase.</p></div></div><div class="how-grid"><div class="how-card"><span class="how-num">01</span><h3>Run on HTTPS or localhost</h3><p>Open the project through a development server. PWA installation does not work from a local file opened as file://.</p></div><div class="how-card"><span class="how-num">02</span><h3>Android or Chrome</h3><p>Open TravelConnect and choose Install app or Add to Home screen from the browser menu.</p></div><div class="how-card"><span class="how-num">03</span><h3>iPhone or iPad</h3><p>In Safari, use Share → Add to Home Screen where supported.</p></div></div><div class="legal-note">For installability on another device, deploy the site with HTTPS. Accounts and bookings are stored in the backend. Weather requires an external provider; payments and GPS remain separate integrations.</div></div>`}
function save(){try{localStorage.setItem(STORE,JSON.stringify({search:state.search,maxPrice:state.maxPrice,verifiedOnly:state.verifiedOnly,selected:state.selected,activeBooking:state.activeBooking,ai:state.ai}))}catch{}}
function loginRequired(title){return `<div class="container page-shell"><section class="surface" style="max-width:610px;margin:35px auto"><h2>${esc(title)}</h2><p class="muted" style="margin:15px 0">Sign in or create an account to continue. Your reservations and messages will be available from other devices.</p>${btn('Sign in or register','open-auth')}</section></div>`}
function authPage(){return `<div class="container page-shell"><div class="page-heading"><div><h2>${loginMode==='login'?'Welcome back':'Create your account'}</h2><p>${loginMode==='login'?'Sign in to TravelConnect':'Join TravelConnect to book verified journeys.'}</p></div></div><div class="profile-grid"><section class="surface auth-surface"><div class="buttons" style="margin-bottom:24px"><button class="button ${loginMode==='login'?'':'secondary'}" data-action="switch-auth" data-mode="login">Sign in</button><button class="button ${loginMode==='register'?'':'secondary'}" data-action="switch-auth" data-mode="register">Register</button></div><form id="auth-form">${loginMode==='register'?field('Full name','<input type="text" name="name" minlength="2" maxlength="70" autocomplete="name" required/>'):''}${field('Email address','<input type="email" name="email" maxlength="254" autocomplete="email" required/>')}${field('Password',`<input type="password" name="password" minlength="10" maxlength="128" autocomplete="${loginMode==='login'?'current-password':'new-password'}" required/>`)}<button class="button full" style="margin-top:22px" type="submit">${loginMode==='login'?'Sign in':'Create account'}</button></form><div class="auth-divider">Or sign in using</div>${googleButton(false)}</section><section class="surface"><h3>Travel safer, together.</h3><p class="muted" style="margin-top:14px">Your account enables bookings, private trip messages, driver applications and access across devices.</p><div class="legal-note">Driver approvals involve a manual administrator review. Google sign-in is available when the Firebase project is configured. Payments, live location, external driver identity checks and emergency dispatch are not connected yet.</div></section></div></div>`}
async function apiFetch(path,options={}){
 const res=await fetch(`${API_BASE}${path}`,{...options,credentials:'same-origin',headers:{'X-TravelConnect-Client':'web',...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});
 let json;try{json=await res.json()}catch{throw Error('Unable to read server response')}
 if(!res.ok)throw Error(json.error||`Server error: ${res.status}`);return json;
}
async function refreshTrips(){try{const result=await apiFetch('/trips');remoteTrips=result.data||[];serverError=''}catch(err){remoteTrips=[];serverError=`Unable to load live journeys: ${err.message}`;}render()}
async function refreshBookings(){if(!currentUser){state.bookings=[];render();return}try{const r=await apiFetch('/bookings');state.bookings=r.data||[]}catch(err){notify(err.message)}render()}
async function refreshDriver(){if(currentUser?.role!=='driver'){render();return}try{const [t,b]=await Promise.all([apiFetch('/driver/trips'),apiFetch('/driver/bookings')]);driverTrips=t.data||[];driverBookings=b.data||[]}catch(err){notify(err.message)}render()}
async function refreshAdmin(){if(currentUser?.role!=='admin'){render();return}try{const [a,d,o]=await Promise.all([apiFetch('/admin/stats'),apiFetch('/admin/drivers?status=pending'),apiFetch('/admin/overview')]);adminStats=a.data;adminDrivers=d.data||[];adminOverview=o.data}catch(err){notify(err.message)}render()}
async function refreshMessages(){if(!currentUser||!chatTripId)return;try{const response=await apiFetch(`/trips/${encodeURIComponent(chatTripId)}/messages`);messages=response.data||[]}catch(err){notify(err.message)}render()}
function refreshRoute(route){if(route==='search'||route==='detail'||route==='checkout')void refreshTrips();if(route==='trips'||route==='track')void refreshBookings();if(route==='driver')void refreshDriver();if(route==='admin')void refreshAdmin();if(route==='detail'){const trip=findTrip(state.selected);if(trip&&trip.date<=dateISO(new Date(Date.now()+15*86400000))&&!weatherForCity[trip.to+':'+trip.date])void fetchWeather(trip.to,trip.date)}if(route==='chat')void refreshMessages()}
function requireAuth(next){if(currentUser)return true;afterLogin=next||'search';go('auth');return false}
async function initialLoad(){try{const user=await apiFetch('/auth/me');currentUser=user.user;state.profile.name=currentUser?.name||'Guest';state.profile.phone=currentUser?.phone||''}catch(err){serverError=`Cannot connect to TravelConnect: ${err.message}`}
 await refreshTrips();try{const ai=await apiFetch('/ai/status');aiEnabled=Boolean(ai.enabled);aiProvider=ai.provider||'Ollama';aiStatusMessage=ai.message||'';}catch{aiEnabled=false;aiStatusMessage='Cannot check local AI status. Restart the server and Ollama.';}if(currentUser)await refreshBookings();render();void prepareGoogleSignIn();}

const routes={home,search,detail,checkout,booked,trips:myTrips,track,chat,assistant,driver,admin,profile,auth:authPage,safety,install:installHelp,weather:weatherPage};
function render(){const route=location.hash.slice(1).split('?')[0]||'home';app.innerHTML=(routes[route]||home)();document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===route||(['detail','checkout','booked'].includes(route)&&el.dataset.nav==='search')||(['track','chat'].includes(route)&&el.dataset.nav==='trips')));document.querySelector('#header-initials').textContent=initials(currentUser?.name||'Guest');document.querySelector('#year').textContent=new Date().getFullYear();if(route==='chat'||route==='assistant'){const list=app.querySelector('.chat-messages');if(list)list.scrollTop=list.scrollHeight;}}
function submitSearch(form){const f=new FormData(form);const from=String(f.get('from')),to=String(f.get('to'));if(from===to)return notify('Choose two different cities.');state.search={from,to,date:String(f.get('date')),seats:Number(f.get('seats'))};save();go('search')}
async function sendAI(q){if(aiBusy)return;aiBusy=true;state.ai.push({name:'You',text:q,mine:true});state.ai=state.ai.slice(-20);save();render();
try{
 if(aiEnabled){if(!currentUser){afterLogin='assistant';notify('Sign in to use live TripAI');go('auth');return;}const r=await apiFetch('/ai/ask',{method:'POST',body:JSON.stringify({question:q})});state.ai.push({name:'TripAI · '+(r.data.provider||aiProvider),text:r.data.reply,mine:false});}
 else state.ai.push({name:'TripAI · setup needed',text:aiStatusMessage||'Install Ollama and download the qwen3:1.7b model, then refresh TravelConnect.',mine:false});
}catch(err){state.ai.push({name:'TripAI · connection error',text:'Live AI is unavailable: '+err.message,mine:false});}
finally{aiBusy=false;state.ai=state.ai.slice(-20);save();render();}}
let deferredInstall=null;
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstall=event;const button=document.querySelector('#install-btn');if(button)button.hidden=false});
window.addEventListener('appinstalled',()=>{deferredInstall=null;const button=document.querySelector('#install-btn');if(button)button.hidden=true;notify('TravelConnect installed');});
if('serviceWorker' in navigator && location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.matches('#search-form,#auth-form,#profile-form,#publish-form,#driver-apply-form,#chat-form,#ai-form,#weather-form'))return;
 event.preventDefault();if(form.id==='search-form')return submitSearch(form);if(form.id==='weather-form'){const f=new FormData(form);await fetchWeather(String(f.get('weather-city')),String(f.get('weather-date')));return;}
 const d=Object.fromEntries(new FormData(form));
 try{
  if(form.id==='auth-form'){
   const isSignup=loginMode==='register';const result=await apiFetch(isSignup?'/auth/register':'/auth/login',{method:'POST',body:JSON.stringify(d)});
   currentUser=result.user;state.profile.name=result.user.name;state.profile.phone=result.user.phone||'';notify(isSignup?'Account created successfully':'Signed in successfully');go(afterLogin||'search');return;
  }
  if(form.id==='profile-form'){const result=await apiFetch('/auth/me',{method:'PATCH',body:JSON.stringify(d)});currentUser=result.user;state.profile.name=currentUser.name;state.profile.phone=currentUser.phone;render();notify('Profile saved in the database');return;}
  if(form.id==='driver-apply-form'){const r=await apiFetch('/driver/apply',{method:'POST',body:JSON.stringify(d)});currentUser=r.user;go('driver');notify('Application submitted for manual review');return;}
  if(form.id==='publish-form'){if(!requireAuth('driver'))return;const r=await apiFetch('/driver/trips',{method:'POST',body:JSON.stringify(d)});notify('Journey published to TravelConnect');await refreshDriver();await refreshTrips();return;}
  if(form.id==='chat-form'){if(!chatTripId)return;await apiFetch(`/trips/${encodeURIComponent(chatTripId)}/messages`,{method:'POST',body:JSON.stringify({message:d.message})});await refreshMessages();return;}
  if(form.id==='ai-form'){if(d.question?.trim())await sendAI(String(d.question).trim());return;}
 }catch(err){notify(err.message)}
});
document.addEventListener('change',event=>{
 if(event.target.id==='filter-price'){state.maxPrice=Number(event.target.value);save();render()}
 if(event.target.id==='filter-verified'){state.verifiedOnly=event.target.checked;save();render()}
 if(event.target.name==='filter-from'){state.search.from=event.target.value;save();render()}
 if(event.target.name==='filter-to'){state.search.to=event.target.value;save();render()}
});
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action],[data-nav],#filter-toggle');if(!el)return;
 if(el.id==='filter-toggle'){event.preventDefault();document.querySelector('.filters')?.classList.toggle('open');return;}
 const action=el.dataset.action;if(!action){if(el.dataset.nav){event.preventDefault();go(el.dataset.nav)}return}
 event.preventDefault();
 try{
  if(action==='weather')return go('weather');if(action==='weather-city'){weatherCity=el.dataset.city;go('weather');return fetchWeather(weatherCity,weatherDate)}if(action==='trip-weather')return fetchWeather(el.dataset.city,el.dataset.date);if(action==='refresh-admin')return refreshAdmin();if(action==='browse')return go('search');if(action==='driver')return go('driver');if(action==='route'){state.search={...state.search,from:el.dataset.from,to:el.dataset.to};save();return go('search')}
  if(action==='reset-search'){state.maxPrice=5000;state.verifiedOnly=false;state.search={...state.search,from:'Johannesburg',to:'Durban',date:dateISO(tomorrow)};save();return go('home')}
  if(action==='detail'){state.selected=el.dataset.id||state.selected;save();return go('detail')}
  if(action==='checkout'){if(!requireAuth('checkout'))return;return go('checkout')}
  if(action==='open-auth'){afterLogin=location.hash.slice(1)||'profile';return go('auth')}
  if(action==='switch-auth'){loginMode=el.dataset.mode||'login';return render()}
  if(action==='google-signin')return handleGoogleSignIn();
  if(action==='firebase-check')return checkGoogleConfiguration(true);
  if(action==='confirm-booking'){
   if(!requireAuth('checkout')||bookingBusy)return;
   const t=findTrip(state.selected);if(!t)throw Error('Journey is no longer available');
   bookingBusy=true;
   try {
     const key=`${t.id}:${state.search.seats}`;
     if(!lastBookingRequest||lastBookingRequest.key!==key)lastBookingRequest={key,id:crypto.randomUUID()};
     const response=await apiFetch('/bookings',{method:'POST',body:JSON.stringify({tripId:t.id,seats:state.search.seats,requestId:lastBookingRequest.id})});
     await refreshBookings();state.latestBooking=response.data.id;state.activeBooking=response.data.id;
     lastBookingRequest=null;await refreshTrips();go('booked');return;
   } finally {bookingBusy=false;}
  }
  if(action==='my-trips')return go('trips');
  if(action==='track'){state.activeBooking=el.dataset.id;const b=state.bookings.find(v=>v.id===el.dataset.id);chatTripId=b?.tripId||null;save();return go('track')}
  if(action==='chat'){const b=state.bookings.find(v=>v.id===state.activeBooking);chatTripId=b?.tripId||chatTripId;return go('chat')}
  if(action==='driver-chat'){chatTripId=el.dataset.id;return go('chat')}
  if(action==='refresh-chat')return refreshMessages();
  if(action==='cancel-booking'){if(!confirm('Cancel this reservation and release the seats?'))return;await apiFetch(`/bookings/${encodeURIComponent(el.dataset.id)}/cancel`,{method:'POST',body:'{}'});await refreshBookings();await refreshTrips();notify('Reservation cancelled; seats released');return}
  if(action==='delete-trip'){if(!confirm('Cancel this journey? It must not have active bookings.'))return;await apiFetch(`/driver/trips/${encodeURIComponent(el.dataset.id)}`,{method:'DELETE'});await refreshDriver();await refreshTrips();notify('Journey cancelled');return}
  if(action==='approve-driver'||action==='reject-driver'){const review=action==='approve-driver'?'approve':'reject';if(!confirm('Have you independently completed the required driver and vehicle checks?'))return;await apiFetch(`/admin/drivers/${encodeURIComponent(el.dataset.id)}/${review}`,{method:'POST',body:'{}'});await refreshAdmin();notify('Application reviewed');return}
  if(action==='refresh-account'){const r=await apiFetch('/auth/me');currentUser=r.user;render();return}
  if(action==='logout'){await apiFetch('/auth/logout',{method:'POST',body:'{}'});currentUser=null;state.bookings=[];driverTrips=[];driverBookings=[];messages=[];state.profile.name='Guest';go('home');notify('Signed out');return}
  if(action==='safety')return go('safety');if(action==='admin')return go('admin');if(action==='install-help')return go('install');if(action==='ask')return sendAI(el.dataset.question);
  if(action==='install'&&deferredInstall){deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;return}if(action==='install')return go('install');
 }catch(err){notify(err.message)}
});
window.addEventListener('hashchange',()=>{render();refreshRoute(location.hash.slice(1)||'home')});
initialLoad();
